SELECT @@VERSION AS version, DB_NAME() AS db, SCHEMA_NAME() AS default_schema, SUSER_NAME() AS login_name, IS_SRVROLEMEMBER('sysadmin') AS is_sysadmin, IS_MEMBER('db_owner') AS is_db_owner
SELECT TABLE_SCHEMA, TABLE_NAME, TABLE_TYPE FROM INFORMATION_SCHEMA.TABLES ORDER BY TABLE_SCHEMA, TABLE_NAME
SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE, CHARACTER_MAXIMUM_LENGTH, NUMERIC_PRECISION, NUMERIC_SCALE, IS_NULLABLE, COLUMN_DEFAULT FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_NAME IN ('customers','orders','products') ORDER BY TABLE_NAME, ORDINAL_POSITION
SELECT o.name AS obj_name, o.type_desc, SCHEMA_NAME(o.schema_id) AS sch, o.create_date, o.modify_date FROM sys.objects o WHERE o.is_ms_shipped = 0 ORDER BY o.type_desc, o.name
SELECT OBJECT_DEFINITION(OBJECT_ID('dbo.usp_CustomerOrderSummary')) AS proc_def
SELECT 'customers' AS tbl, COUNT(*) AS rows_cnt FROM dbo.customers UNION ALL SELECT 'orders', COUNT(*) FROM dbo.orders UNION ALL SELECT 'products', COUNT(*) FROM dbo.products
CREATE TABLE dbo.acct_accounts (   account_id   INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_acct_accounts PRIMARY KEY,   account_code VARCHAR(10)  NOT NULL CONSTRAINT UQ_acct_accounts_code UNIQUE,   account_name NVARCHAR(80) NOT NULL,   account_type VARCHAR(10)  NOT NULL,   normal_side  CHAR(1)      NOT NULL,   is_active    BIT          NOT NULL CONSTRAINT DF_acct_accounts_active DEFAULT (1),   created_at   DATETIME2(0) NOT NULL CONSTRAINT DF_acct_accounts_created DEFAULT (SYSUTCDATETIME()),   CONSTRAINT CK_acct_accounts_type CHECK (account_type IN ('ASSET','LIABILITY','EQUITY','REVENUE','EXPENSE')),   CONSTRAINT CK_acct_accounts_side CHECK (normal_side IN ('D','C')),   CONSTRAINT CK_acct_accounts_code CHECK (account_code NOT LIKE '%[^0-9]%') )
CREATE TABLE dbo.acct_periods (   period_id   INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_acct_periods PRIMARY KEY,   period_name CHAR(7)     NOT NULL CONSTRAINT UQ_acct_periods_name UNIQUE,   start_date  DATE        NOT NULL,   end_date    DATE        NOT NULL,   is_closed   BIT         NOT NULL CONSTRAINT DF_acct_periods_closed DEFAULT (0),   closed_at   DATETIME2(0) NULL,   CONSTRAINT CK_acct_periods_range CHECK (end_date >= start_date) )
CREATE TABLE dbo.acct_journal_entries (   entry_id    INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_acct_journal_entries PRIMARY KEY,   entry_no    VARCHAR(20)  NOT NULL CONSTRAINT UQ_acct_entries_no UNIQUE,   entry_date  DATE         NOT NULL,   description NVARCHAR(200) NOT NULL,   source      VARCHAR(20)  NOT NULL CONSTRAINT DF_acct_entries_source DEFAULT ('MANUAL'),   status      VARCHAR(10)  NOT NULL CONSTRAINT DF_acct_entries_status DEFAULT ('DRAFT'),   posted_at   DATETIME2(0) NULL,   created_at  DATETIME2(0) NOT NULL CONSTRAINT DF_acct_entries_created DEFAULT (SYSUTCDATETIME()),   CONSTRAINT CK_acct_entries_status CHECK (status IN ('DRAFT','POSTED','VOID')) )
CREATE TABLE dbo.acct_journal_lines (   line_id    INT IDENTITY(1,1) NOT NULL CONSTRAINT PK_acct_journal_lines PRIMARY KEY,   entry_id   INT          NOT NULL,   line_no    SMALLINT     NOT NULL,   account_id INT          NOT NULL,   debit      DECIMAL(12,2) NOT NULL CONSTRAINT DF_acct_lines_debit DEFAULT (0),   credit     DECIMAL(12,2) NOT NULL CONSTRAINT DF_acct_lines_credit DEFAULT (0),   memo       NVARCHAR(120) NULL,   CONSTRAINT FK_acct_lines_entry   FOREIGN KEY (entry_id)   REFERENCES dbo.acct_journal_entries(entry_id) ON DELETE CASCADE,   CONSTRAINT FK_acct_lines_account FOREIGN KEY (account_id) REFERENCES dbo.acct_accounts(account_id),   CONSTRAINT UQ_acct_lines_entry_line UNIQUE (entry_id, line_no),   CONSTRAINT CK_acct_lines_nonneg CHECK (debit >= 0 AND credit >= 0),   CONSTRAINT CK_acct_lines_oneside CHECK ((debit = 0 AND credit > 0) OR (credit = 0 AND debit > 0)) )
CREATE TABLE dbo.acct_audit_log (   log_id     BIGINT IDENTITY(1,1) NOT NULL CONSTRAINT PK_acct_audit_log PRIMARY KEY,   entry_id   INT           NULL,   action     VARCHAR(20)   NOT NULL,   actor      VARCHAR(60)   NOT NULL CONSTRAINT DF_acct_audit_actor DEFAULT (SUSER_SNAME()),   detail     NVARCHAR(300) NULL,   logged_at  DATETIME2(3)  NOT NULL CONSTRAINT DF_acct_audit_logged DEFAULT (SYSUTCDATETIME()) )
CREATE INDEX IX_acct_lines_account ON dbo.acct_journal_lines(account_id, entry_id) INCLUDE (debit, credit)
CREATE INDEX IX_acct_entries_date ON dbo.acct_journal_entries(entry_date, status) INCLUDE (entry_no, source)
