CREATE PROCEDURE dbo.usp_probe_nosemi AS BEGIN SET NOCOUNT ON SELECT 1 AS one END
CREATE PROCEDURE dbo.usp_probe_literalsemi AS BEGIN SELECT CAST('a;b' AS VARCHAR(10)) AS probe_value END
CREATE PROCEDURE dbo.usp_probe_raise AS BEGIN SET NOCOUNT ON IF 1 = 0 BEGIN RAISERROR('probe failure', 16, 1) END SELECT 8 AS eight END
CREATE PROCEDURE dbo.usp_AddJournalEntry     @entry_no VARCHAR(20),     @entry_date DATE,     @description NVARCHAR(200),     @source VARCHAR(20) = 'MANUAL' AS BEGIN     SET NOCOUNT ON     IF EXISTS (SELECT 1 FROM dbo.acct_periods WHERE @entry_date BETWEEN start_date AND end_date AND is_closed = 1)     BEGIN         RAISERROR('The accounting period for that date is closed.', 16, 1)         RETURN     END     IF EXISTS (SELECT 1 FROM dbo.acct_journal_entries WHERE entry_no = @entry_no)     BEGIN         RAISERROR('That entry number already exists.', 16, 1)         RETURN     END     INSERT INTO dbo.acct_journal_entries (entry_no, entry_date, description, source)     VALUES (@entry_no, @entry_date, @description, @source)     DECLARE @new_id INT = SCOPE_IDENTITY()     INSERT INTO dbo.acct_audit_log (entry_id, action, detail)     VALUES (@new_id, 'CREATE', CONCAT('entry ', @entry_no))     SELECT @new_id AS entry_id, @entry_no AS entry_no, 'DRAFT' AS status END
CREATE PROCEDURE dbo.usp_AddJournalLine     @entry_no VARCHAR(20),     @line_no SMALLINT,     @account_code VARCHAR(10),     @debit DECIMAL(12,2) = 0,     @credit DECIMAL(12,2) = 0,     @memo NVARCHAR(120) = NULL AS BEGIN     SET NOCOUNT ON     DECLARE @entry_id INT, @status VARCHAR(10)     SELECT @entry_id = entry_id, @status = status     FROM dbo.acct_journal_entries WHERE entry_no = @entry_no     IF @entry_id IS NULL     BEGIN         RAISERROR('Unknown entry number.', 16, 1)         RETURN     END     IF @status <> 'DRAFT'     BEGIN         RAISERROR('Only draft entries can be changed.', 16, 1)         RETURN     END     DECLARE @account_id INT     SELECT @account_id = account_id     FROM dbo.acct_accounts WHERE account_code = @account_code AND is_active = 1     IF @account_id IS NULL     BEGIN         RAISERROR('Unknown or inactive account code.', 16, 1)         RETURN     END     INSERT INTO dbo.acct_journal_lines (entry_id, line_no, account_id, debit, credit, memo)     VALUES (@entry_id, @line_no, @account_id, @debit, @credit, @memo)     SELECT @entry_id AS entry_id, @line_no AS line_no, @account_code AS account_code END
CREATE PROCEDURE dbo.usp_PostJournalEntry     @entry_no VARCHAR(20) AS BEGIN     SET NOCOUNT ON     SET XACT_ABORT ON     DECLARE @entry_id INT, @status VARCHAR(10), @entry_date DATE, @lines INT     DECLARE @debits DECIMAL(14,2), @credits DECIMAL(14,2)     SELECT @entry_id = entry_id, @status = status, @entry_date = entry_date     FROM dbo.acct_journal_entries WHERE entry_no = @entry_no     IF @entry_id IS NULL     BEGIN         RAISERROR('Unknown entry number.', 16, 1)         RETURN     END     IF @status <> 'DRAFT'     BEGIN         RAISERROR('Entry is not a draft, so it cannot be posted.', 16, 1)         RETURN     END     IF EXISTS (SELECT 1 FROM dbo.acct_periods WHERE @entry_date BETWEEN start_date AND end_date AND is_closed = 1)     BEGIN         RAISERROR('Accounting period is closed.', 16, 1)         RETURN     END     SELECT @lines = COUNT(*), @debits = ISNULL(SUM(debit), 0), @credits = ISNULL(SUM(credit), 0)     FROM dbo.acct_journal_lines WHERE entry_id = @entry_id     IF @lines < 2     BEGIN         RAISERROR('A journal entry needs at least two lines.', 16, 1)         RETURN     END     IF @debits <> @credits     BEGIN         RAISERROR('Entry is not balanced: total debits must equal total credits.', 16, 1)         RETURN     END     BEGIN TRY         BEGIN TRANSACTION         UPDATE dbo.acct_journal_entries SET status = 'POSTED', posted_at = SYSUTCDATETIME() WHERE entry_id = @entry_id         INSERT INTO dbo.acct_audit_log (entry_id, action, detail)         VALUES (@entry_id, 'POST', CONCAT('posted ', @lines, ' lines totalling ', CONVERT(VARCHAR(20), @debits)))         COMMIT TRANSACTION     END TRY     BEGIN CATCH         IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION         DECLARE @msg NVARCHAR(300) = ERROR_MESSAGE()         RAISERROR(@msg, 16, 1)     END CATCH     SELECT @entry_no AS entry_no, 'POSTED' AS status, @lines AS line_count,            @debits AS total_debit, @credits AS total_credit END
CREATE PROCEDURE dbo.usp_VoidJournalEntry     @entry_no VARCHAR(20),     @reason NVARCHAR(200) = NULL AS BEGIN     SET NOCOUNT ON     DECLARE @entry_id INT, @status VARCHAR(10), @entry_date DATE     SELECT @entry_id = entry_id, @status = status, @entry_date = entry_date     FROM dbo.acct_journal_entries WHERE entry_no = @entry_no     IF @entry_id IS NULL     BEGIN         RAISERROR('Unknown entry number.', 16, 1)         RETURN     END     IF @status = 'VOID'     BEGIN         RAISERROR('Entry is already void.', 16, 1)         RETURN     END     IF EXISTS (SELECT 1 FROM dbo.acct_periods WHERE @entry_date BETWEEN start_date AND end_date AND is_closed = 1)     BEGIN         RAISERROR('Accounting period is closed.', 16, 1)         RETURN     END     UPDATE dbo.acct_journal_entries SET status = 'VOID' WHERE entry_id = @entry_id     INSERT INTO dbo.acct_audit_log (entry_id, action, detail)     VALUES (@entry_id, 'VOID', @reason)     SELECT @entry_no AS entry_no, 'VOID' AS status END
CREATE PROCEDURE dbo.usp_TrialBalance     @as_of DATE = NULL,     @include_draft BIT = 0 AS BEGIN     SET NOCOUNT ON     IF @as_of IS NULL SET @as_of = CAST(SYSUTCDATETIME() AS DATE)     SELECT a.account_code, a.account_name, a.account_type, a.normal_side,            SUM(CASE WHEN l.debit > 0 THEN l.debit ELSE 0 END) AS debit_total,            SUM(CASE WHEN l.credit > 0 THEN l.credit ELSE 0 END) AS credit_total,            SUM(l.debit - l.credit) AS net_debit,            SUM(CASE WHEN a.normal_side = 'D' THEN l.debit - l.credit ELSE l.credit - l.debit END) AS balance     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     JOIN dbo.acct_accounts a ON a.account_id = l.account_id     WHERE e.entry_date <= @as_of       AND (e.status = 'POSTED' OR (@include_draft = 1 AND e.status = 'DRAFT'))     GROUP BY a.account_code, a.account_name, a.account_type, a.normal_side     ORDER BY a.account_code END
CREATE PROCEDURE dbo.usp_AccountLedger     @account_code VARCHAR(10),     @date_from DATE = NULL,     @date_to DATE = NULL AS BEGIN     SET NOCOUNT ON     DECLARE @account_id INT, @normal CHAR(1)     SELECT @account_id = account_id, @normal = normal_side     FROM dbo.acct_accounts WHERE account_code = @account_code     IF @account_id IS NULL     BEGIN         RAISERROR('Unknown account code.', 16, 1)         RETURN     END     IF @date_from IS NULL SET @date_from = '1900-01-01'     IF @date_to IS NULL SET @date_to = '9999-12-31'     SELECT e.entry_no, e.entry_date, l.line_no, l.memo, l.debit, l.credit,            SUM(CASE WHEN @normal = 'D' THEN l.debit - l.credit ELSE l.credit - l.debit END)                OVER (ORDER BY e.entry_date, e.entry_no, l.line_no                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_balance     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     WHERE l.account_id = @account_id       AND e.status = 'POSTED'       AND e.entry_date BETWEEN @date_from AND @date_to     ORDER BY e.entry_date, e.entry_no, l.line_no END
CREATE PROCEDURE dbo.usp_ClosePeriod     @period_name CHAR(7) AS BEGIN     SET NOCOUNT ON     DECLARE @period_id INT, @start DATE, @end DATE, @closed BIT, @drafts INT     SELECT @period_id = period_id, @start = start_date, @end = end_date, @closed = is_closed     FROM dbo.acct_periods WHERE period_name = @period_name     IF @period_id IS NULL     BEGIN         RAISERROR('Unknown period.', 16, 1)         RETURN     END     IF @closed = 1     BEGIN         RAISERROR('Period is already closed.', 16, 1)         RETURN     END     SELECT @drafts = COUNT(*) FROM dbo.acct_journal_entries     WHERE entry_date BETWEEN @start AND @end AND status = 'DRAFT'     IF @drafts > 0     BEGIN         RAISERROR('Cannot close the period: draft entries still exist in it.', 16, 1)         RETURN     END     IF EXISTS (SELECT 1 FROM dbo.acct_journal_lines l                JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id                WHERE e.entry_date BETWEEN @start AND @end AND e.status = 'POSTED'                HAVING SUM(l.debit) <> SUM(l.credit))     BEGIN         RAISERROR('Cannot close the period: posted entries do not balance.', 16, 1)         RETURN     END     UPDATE dbo.acct_periods SET is_closed = 1, closed_at = SYSUTCDATETIME() WHERE period_id = @period_id     INSERT INTO dbo.acct_audit_log (entry_id, action, detail)     VALUES (NULL, 'CLOSE', CONCAT('period ', @period_name))     SELECT @period_name AS period_name, 'CLOSED' AS status END
CREATE PROCEDURE dbo.usp_ProfitAndLoss     @date_from DATE,     @date_to DATE AS BEGIN     SET NOCOUNT ON     DECLARE @revenue DECIMAL(14,2), @expense DECIMAL(14,2)     SELECT @revenue = ISNULL(SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE 0 END), 0),            @expense = ISNULL(SUM(CASE WHEN a.account_type = 'EXPENSE' THEN l.debit - l.credit ELSE 0 END), 0)     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     JOIN dbo.acct_accounts a ON a.account_id = l.account_id     WHERE e.status = 'POSTED' AND e.entry_date BETWEEN @date_from AND @date_to     SELECT a.account_type, a.account_code, a.account_name,            SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END) AS amount     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     JOIN dbo.acct_accounts a ON a.account_id = l.account_id     WHERE e.status = 'POSTED' AND e.entry_date BETWEEN @date_from AND @date_to       AND a.account_type IN ('REVENUE', 'EXPENSE')     GROUP BY a.account_type, a.account_code, a.account_name     ORDER BY a.account_type DESC, a.account_code     SELECT @revenue AS total_revenue, @expense AS total_expense, @revenue - @expense AS net_result END
CREATE FUNCTION dbo.fn_AccountBalance(@account_code VARCHAR(10), @as_of DATE) RETURNS DECIMAL(14,2) AS BEGIN     DECLARE @bal DECIMAL(14,2)     SELECT @bal = SUM(CASE WHEN a.normal_side = 'D' THEN l.debit - l.credit ELSE l.credit - l.debit END)     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     JOIN dbo.acct_accounts a ON a.account_id = l.account_id     WHERE a.account_code = @account_code       AND e.status = 'POSTED'       AND e.entry_date <= @as_of     RETURN ISNULL(@bal, 0) END
CREATE VIEW dbo.vw_TrialBalance AS SELECT a.account_code, a.account_name, a.account_type, a.normal_side,        ISNULL(SUM(CASE WHEN l.debit > 0 THEN l.debit ELSE 0 END), 0) AS debit_total,        ISNULL(SUM(CASE WHEN l.credit > 0 THEN l.credit ELSE 0 END), 0) AS credit_total,        ISNULL(SUM(CASE WHEN a.normal_side = 'D' THEN l.debit - l.credit ELSE l.credit - l.debit END), 0) AS balance FROM dbo.acct_accounts a LEFT JOIN dbo.acct_journal_lines l ON l.account_id = a.account_id LEFT JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id AND e.status = 'POSTED' GROUP BY a.account_code, a.account_name, a.account_type, a.normal_side
CREATE OR ALTER VIEW dbo.vw_TrialBalance AS SELECT a.account_code, a.account_name, a.account_type, a.normal_side,        ISNULL(SUM(CASE WHEN e.entry_id IS NOT NULL AND l.debit > 0 THEN l.debit ELSE 0 END), 0) AS debit_total,        ISNULL(SUM(CASE WHEN e.entry_id IS NOT NULL AND l.credit > 0 THEN l.credit ELSE 0 END), 0) AS credit_total,        ISNULL(SUM(CASE WHEN e.entry_id IS NOT NULL AND a.normal_side = 'D' THEN l.debit - l.credit                        WHEN e.entry_id IS NOT NULL THEN l.credit - l.debit ELSE 0 END), 0) AS balance FROM dbo.acct_accounts a LEFT JOIN dbo.acct_journal_lines l ON l.account_id = a.account_id LEFT JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id AND e.status = 'POSTED' GROUP BY a.account_code, a.account_name, a.account_type, a.normal_side
CREATE PROCEDURE dbo.usp_PostClosingEntry     @period_name CHAR(7) AS BEGIN     SET NOCOUNT ON     DECLARE @start DATE, @end DATE, @closed BIT, @entry_no VARCHAR(20), @entry_id INT     DECLARE @net DECIMAL(14,2), @retained INT     SELECT @start = start_date, @end = end_date, @closed = is_closed     FROM dbo.acct_periods WHERE period_name = @period_name     IF @start IS NULL     BEGIN         RAISERROR('Unknown period.', 16, 1)         RETURN     END     IF @closed = 1     BEGIN         RAISERROR('Period is already closed.', 16, 1)         RETURN     END     SET @entry_no = 'CLOSE-' + @period_name     IF EXISTS (SELECT 1 FROM dbo.acct_journal_entries WHERE entry_no = @entry_no)     BEGIN         RAISERROR('The closing entry for this period already exists.', 16, 1)         RETURN     END     SELECT @retained = account_id FROM dbo.acct_accounts WHERE account_code = '3100'     SELECT @net = ISNULL(SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END), 0)     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     JOIN dbo.acct_accounts a ON a.account_id = l.account_id     WHERE e.status = 'POSTED' AND e.entry_date BETWEEN @start AND @end       AND a.account_type IN ('REVENUE', 'EXPENSE')     IF @net = 0     BEGIN         RAISERROR('Nothing to close: revenue and expense net to zero for this period.', 16, 1)         RETURN     END     EXEC dbo.usp_AddJournalEntry @entry_no = @entry_no, @entry_date = @end,          @description = N'Closing entry for the period', @source = 'CLOSE'     SELECT @entry_id = entry_id FROM dbo.acct_journal_entries WHERE entry_no = @entry_no     INSERT INTO dbo.acct_journal_lines (entry_id, line_no, account_id, debit, credit, memo)     SELECT @entry_id,            ROW_NUMBER() OVER (ORDER BY a.account_code),            a.account_id,            CASE WHEN SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END) > 0                 THEN SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END)                 ELSE 0 END,            CASE WHEN SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END) < 0                 THEN -SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END)                 ELSE 0 END,            N'Reverse the account for the period'     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     JOIN dbo.acct_accounts a ON a.account_id = l.account_id     WHERE e.status = 'POSTED' AND e.entry_date BETWEEN @start AND @end       AND a.account_type IN ('REVENUE', 'EXPENSE')     GROUP BY a.account_code, a.account_id     HAVING SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END) <> 0     INSERT INTO dbo.acct_journal_lines (entry_id, line_no, account_id, debit, credit, memo)     SELECT @entry_id, MAX(line_no) + 1, @retained,            CASE WHEN @net < 0 THEN -@net ELSE 0 END,            CASE WHEN @net > 0 THEN @net ELSE 0 END,            N'Net result to retained earnings'     FROM dbo.acct_journal_lines WHERE entry_id = @entry_id     EXEC dbo.usp_PostJournalEntry @entry_no = @entry_no     SELECT @entry_no AS closing_entry, @net AS net_result END
