CREATE OR ALTER PROCEDURE dbo.usp_PostClosingEntry     @period_name CHAR(7) AS BEGIN     SET NOCOUNT ON     DECLARE @start DATE, @end DATE, @closed BIT, @entry_no VARCHAR(20), @entry_id INT     DECLARE @net DECIMAL(14,2), @retained INT     SELECT @start = start_date, @end = end_date, @closed = is_closed     FROM dbo.acct_periods WHERE period_name = @period_name     IF @start IS NULL     BEGIN         RAISERROR('Unknown period.', 16, 1)         RETURN     END     IF @closed = 1     BEGIN         RAISERROR('Period is already closed.', 16, 1)         RETURN     END     SET @entry_no = 'CLOSE-' + @period_name     IF EXISTS (SELECT 1 FROM dbo.acct_journal_entries WHERE entry_no = @entry_no)     BEGIN         RAISERROR('The closing entry for this period already exists.', 16, 1)         RETURN     END     IF NOT EXISTS (SELECT 1 FROM dbo.acct_journal_lines l                    JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id                    JOIN dbo.acct_accounts a ON a.account_id = l.account_id                    WHERE e.status = 'POSTED' AND e.entry_date BETWEEN @start AND @end                      AND a.account_type IN ('REVENUE', 'EXPENSE')                    HAVING SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END) <> 0)     BEGIN         RAISERROR('Nothing to close: the revenue and expense accounts are already empty for this period.', 16, 1)         RETURN     END     SELECT @retained = account_id FROM dbo.acct_accounts WHERE account_code = '3100'     SELECT @net = ISNULL(SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE -(l.debit - l.credit) END), 0)     FROM dbo.acct_journal_lines l     JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id     JOIN dbo.acct_accounts a ON a.account_id = l.account_id     WHERE e.status = 'POSTED' AND e.entry_date BETWEEN @start AND @end       AND a.account_type IN ('REVENUE', 'EXPENSE')     EXEC dbo.usp_AddJournalEntry @entry_no = @entry_no, @entry_date = @end,          @description = N'Closing entry for the period', @source = 'CLOSE'     SELECT @entry_id = entry_id FROM dbo.acct_journal_entries WHERE entry_no = @entry_no     INSERT INTO dbo.acct_journal_lines (entry_id, line_no, account_id, debit, credit, memo)     SELECT @entry_id,            ROW_NUMBER() OVER (ORDER BY x.account_code),            x.account_id,            CASE WHEN x.account_type = 'REVENUE'                 THEN CASE WHEN x.signed > 0 THEN x.signed ELSE 0 END                 ELSE CASE WHEN x.signed < 0 THEN -x.signed ELSE 0 END END,            CASE WHEN x.account_type = 'EXPENSE'                 THEN CASE WHEN x.signed > 0 THEN x.signed ELSE 0 END                 ELSE CASE WHEN x.signed < 0 THEN -x.signed ELSE 0 END END,            N'Reverse the account for the period'     FROM (SELECT a.account_code, a.account_id, a.account_type,                  SUM(CASE WHEN a.account_type = 'REVENUE' THEN l.credit - l.debit ELSE l.debit - l.credit END) AS signed           FROM dbo.acct_journal_lines l           JOIN dbo.acct_journal_entries e ON e.entry_id = l.entry_id           JOIN dbo.acct_accounts a ON a.account_id = l.account_id           WHERE e.status = 'POSTED' AND e.entry_date BETWEEN @start AND @end             AND a.account_type IN ('REVENUE', 'EXPENSE')           GROUP BY a.account_code, a.account_id, a.account_type) AS x     WHERE x.signed <> 0     INSERT INTO dbo.acct_journal_lines (entry_id, line_no, account_id, debit, credit, memo)     SELECT @entry_id, MAX(line_no) + 1, @retained,            CASE WHEN @net < 0 THEN -@net ELSE 0 END,            CASE WHEN @net > 0 THEN @net ELSE 0 END,            N'Net result to retained earnings'     FROM dbo.acct_journal_lines WHERE entry_id = @entry_id HAVING @net <> 0     EXEC dbo.usp_PostJournalEntry @entry_no = @entry_no     SELECT @entry_no AS closing_entry, @net AS net_result END
