CREATE OR ALTER PROCEDURE dbo.usp_AddJournalLine     @entry_no VARCHAR(20),     @line_no SMALLINT,     @account_code VARCHAR(10),     @debit DECIMAL(12,2) = 0,     @credit DECIMAL(12,2) = 0,     @memo NVARCHAR(120) = NULL AS BEGIN     SET NOCOUNT ON     DECLARE @entry_id INT, @status VARCHAR(10), @entry_date DATE     SELECT @entry_id = entry_id, @status = status, @entry_date = entry_date     FROM dbo.acct_journal_entries WHERE entry_no = @entry_no     IF @entry_id IS NULL     BEGIN         RAISERROR('Unknown entry number.', 16, 1)         RETURN     END     IF @status <> 'DRAFT'     BEGIN         RAISERROR('Only draft entries can be changed.', 16, 1)         RETURN     END     IF EXISTS (SELECT 1 FROM dbo.acct_periods WHERE @entry_date BETWEEN start_date AND end_date AND is_closed = 1)     BEGIN         RAISERROR('The accounting period for that entry is closed.', 16, 1)         RETURN     END     DECLARE @account_id INT     SELECT @account_id = account_id     FROM dbo.acct_accounts WHERE account_code = @account_code AND is_active = 1     IF @account_id IS NULL     BEGIN         RAISERROR('Unknown or inactive account code.', 16, 1)         RETURN     END     INSERT INTO dbo.acct_journal_lines (entry_id, line_no, account_id, debit, credit, memo)     VALUES (@entry_id, @line_no, @account_id, @debit, @credit, @memo)     SELECT @entry_id AS entry_id, @line_no AS line_no, @account_code AS account_code END
